<!doctype html><html lang="no"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Googa – somaliske gåter</title><link rel="stylesheet" href="styles.css"><style>.paywall{max-width:760px;margin:7vh auto;background:#fffdf7;border-radius:32px;padding:28px;box-shadow:0 18px 45px #10365422;text-align:center}.price{display:grid;grid-template-columns:1fr 1fr;gap:14px;margin:23px 0}.price div{padding:18px;border-radius:20px;background:#e5f7f7;font-weight:800}.price b{display:block;font:800 31px 'Baloo 2'}.go{border:0;border-radius:16px;background:#0b8691;color:#fff;padding:15px 22px;font-weight:800;font-size:17px}.go[disabled]{opacity:.6;cursor:wait}.qr{margin:22px auto;max-width:320px}.qr canvas{max-width:100%;height:auto}.muted{color:#5b7185}.owner-note{margin-top:18px;padding:12px 14px;border-radius:16px;background:#fff5cb;font-weight:800}.manual{display:block;margin-top:10px;font-weight:800;color:#103654}.retry{margin-top:14px;border:0;border-radius:12px;background:#103654;color:#fff;padding:10px 14px;font-weight:800}</style><main class="paywall"><img src="assets/googa-mascot.png" alt="Googa" width="150"><p class="eyebrow">GOOGA</p><h1>Gåter på somali.<br>Små øyeblikk sammen.</h1><p class="muted">Inviterte eiere får nå valg mellom demo, betalt modus og eierdashbord etter innlogging.</p><div class="price"><div><span>Prøv først</span><b>kr 5</b><small>2 dager</small></div><div><span>Deretter</span><b>kr 50</b><small>per måned</small></div></div><button class="go" id="start">Logg inn med QR-kode</button><section class="qr hidden" id="qr"><p><strong>Skann med telefonen</strong></p><div id="code"></div><a class="manual hidden" id="manualLink" href="#" target="_blank" rel="noopener">Åpne innlogging på telefonen</a><p class="muted" id="status">Lager sikker QR-kode …</p><button class="retry hidden" id="retry" type="button">Lag ny kode</button></section><p class="owner-note">Vanlige brukere er fortsatt ikke åpnet i QR-broen. Eierdashbordet er klart for rabatt- og tilgangsstyring når du vil åpne innloggingen bredere.</p></main><script src="assets/vendor/qrcode.bundle.js"></script><script>const q=document.querySelector('#qr'),c=document.querySelector('#code'),s=document.querySelector('#status'),start=document.querySelector('#start'),retry=document.querySelector('#retry'),manual=document.querySelector('#manualLink');let pollTimer=0,activeToken='',pollBusy=false;async function api(action,t){const u='api/auth.php?action='+action+(t?'&t='+encodeURIComponent(t):'');const r=await fetch(u,{cache:'no-store',credentials:'same-origin'});return r.json()}function stopPoll(){if(pollTimer){clearTimeout(pollTimer);pollTimer=0}pollBusy=false}function setRetry(show){retry.classList.toggle('hidden',!show);start.disabled=false}function schedulePoll(){stopPoll();pollTimer=window.setTimeout(runPoll,1500)}async function renderQr(url){c.innerHTML='';const canvas=document.createElement('canvas');c.appendChild(canvas);await window.QRCode.toCanvas(canvas,url,{width:280,margin:1})}async function runPoll(){if(!activeToken||pollBusy)return;pollBusy=true;try{const x=await api('poll',activeToken);if(x.state==='approved'){stopPoll();window.location.replace('./');return}if(x.state==='denied'){stopPoll();s.textContent='Innloggingen ble avvist. Lag en ny kode.';setRetry(true);return}if(x.state==='expired'){stopPoll();s.textContent='Koden er utløpt. Lag en ny.';setRetry(true);return}s.textContent=x.state==='scanned'?'Telefon åpnet. Venter på godkjenning …':'Venter på godkjenning …';pollBusy=false;schedulePoll()}catch(e){s.textContent='Midlertidig nettverksfeil. QR-koden beholdes mens vi prøver igjen …';pollBusy=false;schedulePoll()}}async function beginQr(){stopPoll();activeToken='';start.disabled=true;setRetry(false);q.classList.remove('hidden');c.innerHTML='';manual.classList.add('hidden');s.textContent='Lager sikker QR-kode …';try{const d=await api('create');if(!d.token||!d.scanUrl){s.textContent='Kunne ikke lage QR-kode.';setRetry(true);return}activeToken=d.token;await renderQr(d.scanUrl);manual.href=d.scanUrl;manual.classList.remove('hidden');s.textContent='Venter på godkjenning …';pollBusy=false;schedulePoll()}catch(e){s.textContent='Kunne ikke starte QR-innlogging nå.';setRetry(true)}}start.onclick=beginQr;retry.onclick=beginQr;</script></html>
